local TrailStageMain = Class("TrailStageMain")
function TrailStageMain:__init()
    self.particleGo = nil
    self.particleTopGo = nil
    self.isFocusSetHide = true
end

function TrailStageMain:__delete()
    self.controller = nil
    self.particleGo = nil
    self.particleTopGo = nil
    self.isFocusSetHide = nil

end

function TrailStageMain:Awake()
    trailBattleMgr = TrailBattleMgr:GetInstance()
    if isNull(self.CommonGoodsList.Env) then
        self.CommonGoodsList:Init()
    end
    if isNull(self.TxtTimeState2.Env) then
        self.TxtTimeState2:Init()
    end
    self.EventPlayAnim = Events.AddListener(Constants.EventNames.PlayTrailLevelAnim, function()
        local enterData = trailBattleMgr:GetEnterData()
        if checkNumber(enterData.isFirst) == 1 then
            self.LevelAnimRoot:Play("Pop")
        else
            self.LevelAnimRoot:Play("Default")
        end
    end)
    GameUtils.BindRedPoint(Constants.RedPointConst.TrailQuestTask, self.BtnTask, true)
    self:SetBtnAction()
    self:StartCountDown()
end

function TrailStageMain:OnFocus(focus)
    KTool.SetActive(self.LineEffect, focus)
    --安全起见，先关闭全部的粒子

    --if trailBattleMgr.initialed then
    --    local curSegment = trailBattleMgr:GetMySegment()
    --    local segmentData = trailBattleMgr:GetSegmentRewardVoByRefId(curSegment)
    --    self.particleGo = self["ParticleLevel"..segmentData.icon]
    --end
    if self.particleGo then
        self.isFocusSetHide = not focus
        KTool.SetActive(self.particleGo, focus)
    end
    if self.particleTopGo then
        KTool.SetActive(self.particleTopGo, focus)
    end
end

function TrailStageMain:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        trailBattleMgr:Initialize(function ()
            self:FreshBaseUI()
        end, function ()
            UIRaycastBlocker:AddCondition("TrailStageMainErrTime")
            local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
                coroutine.yield(CS.UnityEngine.WaitForSeconds(0.5))
                UIModule.BackDialog()
            end))
        end)
    end))
    return coWait
end
