function TrailStageMain:SetBtnAction()
    SetButtonAction(self.BtnRanking, function ()
        UIModule.OpenDialog({ id = Constants.UITypeIds.UITrailStageRankDialog })
    end)
    SetButtonAction(self.BtnShop, function ()
        local storeUtils = import('Game.UI.Store.StoreUtils')
        local StoreConstants = import('Game.UI.Store.StoreConstants')
        storeUtils.OpenVarietyStore(StoreConstants.OpenIds.Challenge,{
            {id = Constants.UITypeIds.TrailStageMain}
        })
    end)
    SetButtonAction(self.BtnTask, function ()
        UIModule.OpenDialog({ id = Constants.UITypeIds.UITrailStageTasks })
    end)
    SetButtonAction(self.FontStyleButton, function ()
        UIModule.OpenDialog({ id = Constants.UITypeIds.TrailStageChallenge },{
            {id = Constants.UITypeIds.TrailStageMain}
        })
    end)
    SetButtonAction(self.LevelGroup, function ()
        UIModule.OpenDialog({ id = Constants.UITypeIds.TrailStageParagraphReward })
    end)

end

function TrailStageMain:StartCountDown()
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local trialRemainTime = checkInt(playerComponent.playerDojo.trialRemainTime)
    if trialRemainTime - Constants.MIN_TRIAL_CAN_ENTER > 0 then
        self.FontStyleButton:GetComponent("FontStyleButton"):ResetFontStyle("B1", localize("前往挑战"))
        self.TxtTimeState.text = localize("距离结束")
        self.TxtTimeState2.Env:StartLeftSecond(trialRemainTime - Constants.MIN_TRIAL_CAN_ENTER, 3, function ()
            --CfUtils.FillText(self.TxtTimeState.transform, localize("结算中"))
        end)
    else
        self.TxtTimeState.text = localize("距离开始")
        self.FontStyleButton:GetComponent("FontStyleButton"):ResetFontStyle("B16", localize("结算中"))
        self.TxtTimeState2.Env:StartLeftSecond(trialRemainTime, 2, function ()
            --CfUtils.FillText(self.TxtTimeState.transform, localize("结算中"))
        end)
    end
end

function TrailStageMain:FreshBaseUI()
    ---@region Left
    local enterData = trailBattleMgr:GetEnterData()
    local roomRank = checkTable(enterData.roomRank)
    KTool.SetActive(self.ParticleLevel1, false)
    KTool.SetActive(self.ParticleLevel2, false)
    KTool.SetActive(self.ParticleLevel3, false)
    KTool.SetActive(self.ParticleLevel4, false)
    KTool.SetActive(self.ParticleLevel5, false)


    --table.sort(roomRank, function(a,b)
    --    if a.score ~= b.score then
    --        return a.score < b.score
    --    end
    --    return false
    --end)
    --printInfo("enterData.score==>>"..table.dump(enterData))

    local myData = DeepCopy(trailBattleMgr:GetMyRoomRankInfo())

    myData["isLast"] = true
    myData.posX = 150 --将X坐标归正，默认X轴是在TrailEnterDojo里做了偏移的
    table.insert(roomRank, myData)--插入第21位未上榜数据
    KTool.SetActive(self.LoopView.transform, true)
    self.LoopView:InitListView(table.count(roomRank), roomRank)
    self.LoopView:MovePanelToIndex(myData.order)--加上插入的是21组数据

    ---@endregion
    local curSegment = trailBattleMgr:GetMySegment()
    local segmentData = trailBattleMgr:GetSegmentRewardVoByRefId(curSegment)
    self.TxtDan.text = segmentData.name
    self.ImgLevel.Status = segmentData.icon
    if not self.isFocusSetHide then
        KTool.SetActive(self["ParticleLevel"..segmentData.icon], true)
    end
    self.particleGo = self["ParticleLevel"..segmentData.icon]

    local isUnlisted = checkNumber(enterData.score) <= 0
    local isTopRank = checkNumber(enterData.isTopRank) == 1
    if isTopRank then
        self.particleTopGo = self.Detailed.transform:Find("UIFX_TrailStageBestLevel")
    end
    KTool.SetActive(self.Detailed, isTopRank)
    KTool.SetActive(self.NotonList, isUnlisted)
    KTool.SetActive(self.CommonGoodsList.transform, not isUnlisted)
    if isUnlisted then

    else
        local rewards = {}
        --local rank = checkNumber(enterData.rank)
        if segmentData.upGrade ~= 0 then
            rewards = segmentData.upRewards
            --if rank >= checkNumber(segmentData.upGrade[1]) and rank <= checkNumber(segmentData.upGrade[2]) then
            --    rewards = parse_rewards(segmentData.upPrizeId, segmentData.upPrizeNum)
            --end
        end
        if segmentData.keepGrade ~= 0 then
            rewards = segmentData.keepRewards
            --if rank >= checkNumber(segmentData.keepGrade[1]) and rank <= checkNumber(segmentData.keepGrade[2]) then
            --    rewards = parse_rewards(segmentData.keepPrizeId, segmentData.keepPrizeNum)
            --end
        end
        if segmentData.downGrade ~= 0 then
            rewards = segmentData.downRewards
            --if rank >= checkNumber(segmentData.downGrade[1]) and rank <= checkNumber(segmentData.downGrade[2]) then
            --    rewards = parse_rewards(segmentData.downPrizeId, segmentData.downPrizeNum)
            --end
        end
        self.CommonGoodsList.Env:FreshBaseUI(rewards)

    end
end

function TrailStageMain:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        UIRaycastBlocker:RemoveCondition("TrailStageMainErrTime")
        Events.RemoveListener(Constants.EventNames.PlayTrailLevelAnim, self.EventPlayAnim)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.TrailQuestTask)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return TrailStageMain